import { initI18n } from '@asafarim/shared-i18n';

initI18n({
  defaultLanguage: 'en',
  defaultNS: 'common',
  ns: ['common', 'app'],
  resources: {
    en: { app: enApp },
    lb: { app: lbApp }
  }
});

import {
  CountryLanguageSelector,
  type Country,
  type Locale,
} from '@asafarim/shared-i18n';

<CountryLanguageSelector
  countries={countries}
  value={locale}
  onChange={(locale) => {
    i18n.changeLanguage(locale.language);
    navigate(`/${locale.country.toLowerCase()}-${locale.language}/`);
  }}
  triggerVariant="compact"
  flagMode="image"
/>

import { LanguageSwitcher } from '@asafarim/shared-i18n';

<LanguageSwitcher
  variant="buttons"
  onChanged={(lang) => {
    // map Sprooch → voll Locale fir URL-sächer Routing:
    const { locale } = resolveLocaleFromLanguage(currentLocale, lang, countries);
    navigate(locale);
  }}
/>

